{
  "type": "object",
  "properties": {
    "root_cause": {
      "type": "string",
      "enum": [
        "reefer_unit_fault",
        "defrost_cycle",
        "door_open_dwell",
        "handover_delay",
        "setpoint_error",
        "ambient_exposure",
        "logger_fault",
        "unknown"
      ],
      "description": "Most likely cause, from the events and readings."
    },
    "minutes_out_of_range": {
      "type": "integer",
      "description": "Minutes out of the allowed range in this shipment's log."
    },
    "peak_temp_c": {
      "type": "number",
      "description": "Highest (or, for a low excursion, lowest) reading in Celsius during the excursion."
    },
    "disposition": {
      "type": "string",
      "enum": [
        "quarantine",
        "release",
        "reroute",
        "no_excursion",
        "hold_for_quality"
      ],
      "description": "Proposed disposition."
    },
    "reroute_facility_id": {
      "type": [
        "string",
        "null"
      ],
      "description": "Facility to reroute to, or null."
    },
    "deviation_record": {
      "type": "object",
      "description": "Draft deviation record for the quality approver.",
      "properties": {
        "title": {
          "type": "string",
          "description": "Short title for the deviation."
        },
        "description": {
          "type": "string",
          "description": "What happened, when and where, citing reading timestamps and events."
        },
        "product_impact": {
          "type": "string",
          "description": "Impact against the stability profile: minutes used, budget remaining."
        },
        "immediate_action": {
          "type": "string",
          "description": "The proposed disposition and why."
        },
        "root_cause_hypothesis": {
          "type": "string",
          "description": "Cause and the evidence for it."
        },
        "corrective_action_suggestion": {
          "type": "string",
          "description": "Suggested corrective or preventive action for the quality team to consider."
        }
      },
      "required": [
        "title",
        "description",
        "product_impact",
        "immediate_action",
        "root_cause_hypothesis",
        "corrective_action_suggestion"
      ],
      "additionalProperties": false
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1. How sure you are that the recommendation is right given what the tools returned. Below 0.5 means you are guessing."
    },
    "rationale": {
      "type": "string",
      "description": "Two to five sentences a reviewer can check against the tool results. Cite the record ids you relied on."
    },
    "questions_for_human": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "If a person has to decide, the specific questions they need to answer. Empty when nothing is open."
    }
  },
  "required": [
    "root_cause",
    "minutes_out_of_range",
    "peak_temp_c",
    "disposition",
    "reroute_facility_id",
    "deviation_record",
    "confidence",
    "rationale",
    "questions_for_human"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let out = null;
try { out = one('Exception resolution agent').output ?? null; } catch (e) {} // unreadable output is treated as none

const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = one('Normalize temperature alert'); // one(): defined by guardPreamble; survives a lost item link
// Fresh read: { shipment_id, status, sku, lot, readings: [{ ts, temp_c }], stability: { min_c, max_c, excursion_budget_minutes, prior_excursion_minutes }, logger: { calibration_due } }
const log = $json;
const st = log.stability ?? {};
const readings = (log.readings ?? []).map((r) => ({ t: Date.parse(r.ts), c: Number(r.temp_c) })).filter((r) => Number.isFinite(r.t) && Number.isFinite(r.c)).sort((a, b) => a.t - b.t);
const minC = Number(st.min_c);
const maxC = Number(st.max_c);
const budget = Number(st.excursion_budget_minutes);
const prior = Number(st.prior_excursion_minutes ?? 0);
const outside = (c) => c < minC || c > maxC;
const disp = out?.disposition;

// Recompute time out of range: an interval counts when either end is out of range.
let minutesOut = 0;
let longestGap = 0;
let peak = null;
for (let i = 0; i < readings.length; i++) {
  const r = readings[i];
  if (outside(r.c)) {
    const dev = r.c > maxC ? r.c - maxC : minC - r.c;
    if (peak === null || dev > peak.dev) peak = { dev, c: r.c };
  }
  if (i === 0) continue;
  const gap = (r.t - readings[i - 1].t) / 60000;
  longestGap = Math.max(longestGap, gap);
  if (outside(r.c) || outside(readings[i - 1].c)) minutesOut += gap;
}
minutesOut = Math.round(minutesOut);
const total = prior + minutesOut;
const budgetExceeded = total > budget;
const calibrationExpired = log.logger?.calibration_due ? Date.parse(log.logger.calibration_due) < Date.now() : true;

if (!cfg.open_statuses.includes(log.status)) reasons.push('shipment status is now ' + log.status + ', so it may already have been dispositioned');
if (!Number.isFinite(minC) || !Number.isFinite(maxC) || !Number.isFinite(budget)) reasons.push('no allowed range or excursion budget on record for ' + (log.sku ?? req.sku) + ' lot ' + (log.lot ?? req.lot));
if (readings.length < 2) reasons.push('temperature log has fewer than two readings, so time out of range cannot be established');
if (longestGap > cfg.max_logger_gap_minutes) reasons.push('temperature log has a gap of ' + Math.round(longestGap) + ' minutes (limit ' + cfg.max_logger_gap_minutes + '), so time out of range cannot be established');
if (out && Math.abs(Number(out.minutes_out_of_range) - minutesOut) > cfg.minutes_tolerance) reasons.push('agent counted ' + out.minutes_out_of_range + ' minutes out of range but the log shows ' + minutesOut);
if (disp === 'release' && budgetExceeded) reasons.push('release blocked: ' + total + ' minutes out of range on this lot (' + prior + ' before, ' + minutesOut + ' now) exceeds the excursion budget of ' + budget);
if (disp === 'release' && calibrationExpired) reasons.push('release blocked: logger ' + req.logger_id + ' has no current calibration');
if (disp === 'reroute' && !out?.reroute_facility_id) reasons.push('reroute proposed without a destination facility');
if (disp === 'hold_for_quality') reasons.push('agent asks the quality team to decide');
if (disp === 'no_excursion' && minutesOut > 0) reasons.push('agent reports no excursion but the log shows ' + minutesOut + ' minutes out of range');
const rec = out?.deviation_record;
if (disp && disp !== 'no_excursion' && (!rec?.title || !rec?.description)) reasons.push('deviation record draft is incomplete');

const noop = disp === 'no_excursion' && minutesOut === 0;
const action = {
  type: disp,
  alert_id: req.alert_id,
  shipment_id: req.shipment_id,
  lot: log.lot ?? req.lot,
  allowed_range_c: [minC, maxC],
  minutes_out_of_range: minutesOut,
  lot_excursion_minutes_total: total,
  excursion_budget_minutes: budget,
  peak_temp_c: peak ? peak.c : null,
  reroute_facility_id: disp === 'reroute' ? out?.reroute_facility_id ?? null : null,
  deviation_record: rec ?? null,
};
const summary = 'Shipment ' + req.shipment_id + ' lot ' + action.lot + ': ' + minutesOut + ' minutes outside ' + minC + ' to ' + maxC + ' C'
  + (peak ? ' (peak ' + peak.c + ' C)' : '') + '. Lot total ' + total + ' of ' + budget + ' budget minutes.\n'
  + 'Cause: ' + (out?.root_cause ?? 'unknown') + '. Proposed: *' + disp + '*' + (action.reroute_facility_id ? ' to ' + action.reroute_facility_id : '') + '.\n'
  + (rec?.title ? 'Deviation draft: ' + rec.title + '\n' : '') + (out?.rationale ?? '');
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
// Read the plan even if n8n lost the item link (seen live after the AI Agent node).
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
const planned = one('Guardrails').action;
const expectedStatus = { quarantine: 'quarantined', release: 'released', reroute: 'rerouted' }[planned.type];
const dev = ($json.deviations ?? []).find((d) => d.alert_id === planned.alert_id);
const ok = $json.status === expectedStatus && !!dev && dev.status === 'filed' && dev.disposition === planned.type
  && (planned.type !== 'reroute' || $json.destination_facility_id === planned.reroute_facility_id);
const detail = 'shipment shows status ' + $json.status + ' (expected ' + expectedStatus + '), deviation ' + (dev ? dev.status + ' with ' + dev.disposition : 'not found');
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
// Every lookup is guarded: this node is the safety net, so it must never be the step that fails.
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let intake = null;
let agent = null;
let guard = null;
try { intake = one('Normalize temperature alert'); } catch (e) {}
try { agent = one('Exception resolution agent'); } catch (e) {}
try { guard = one('Guardrails'); } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if (!intake) {
  // n8n could not link this item back to its request. Keep whatever identifies it and say so.
  intake = { business_key: $json.business_key ?? null };
  reasons.push('item_context_lost: the request could not be linked to this failure; check the n8n execution');
}
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const REDACT = [].map((p) => new RegExp(p, 'g'));
const scrub = (text) => REDACT.reduce((t, r) => t.replace(r, '[redacted]'), String(text ?? ''));
// The masks also apply to what the model wrote, in case it repeated a number it read.
const scrubJson = (v) => {
  if (!REDACT.length || v == null) return v;
  try { return JSON.parse(scrub(JSON.stringify(v))); } catch (e) { return scrub(JSON.stringify(v)); }
};
const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: scrub(s.observation).slice(0, 1500),
}));

const summary = 'Cold-chain alert ' + intake.alert_id + ' · shipment ' + intake.shipment_id + ' · proposed ' + (agent?.output?.disposition ?? 'none');
// Slack-safe copies: request, document and model text can contain Slack markup such as <!channel>.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return {
  json: {
    business_key: intake.business_key,
    team: "cold-chain quality",
    reasons,
    proposed: scrubJson(agent?.output ?? null),
    confidence: agent?.output?.confidence ?? null,
    questions: scrubJson(agent?.output?.questions_for_human ?? []),
    trace,
    summary,
    slack: { key: esc(intake.business_key), summary: esc(summary), reasons: esc(reasons.join('; ')) },
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

