// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let intake = null;
let agent = null;
let guard = null;
let approval = null;
try { intake = one('Normalize temperature alert'); } catch (e) {}
try { agent = one('Exception resolution agent'); } catch (e) {}
try { guard = one('Guardrails'); } catch (e) {}
// Present only on workflows with a named-approver step, and only if this run reached it.
try { approval = one('Record approval'); } catch (e) {}

return {
  json: {
    // Escalated runs carry the key from Build exception, so the audit row is written even if
    // the request itself could not be looked up.
    business_key: intake?.business_key ?? $json.business_key ?? null,
    outcome: $json.outcome,
    approval: approval ? { decision: approval.decision, approver: approval.approver, decided_at: approval.decided_at } : null,
    route: guard?.route ?? 'escalate',
    decision: agent?.output ?? null,
    guardrail_reasons: guard?.guardrail_reasons ?? [],
    actions: guard?.planned_actions ?? [],
    tool_calls: (agent?.intermediateSteps ?? []).length,
  },
};
